using System.Security.Cryptography;
using System.Text;
using GlobalRemoteControl.Agent.Crypto;

namespace GlobalRemoteControl.Agent.Tests;

public class CryptoTests
{
    // Generated by Node: crypto.generateKeyPairSync('ec',{namedCurve:'P-256'}); crypto.sign('sha256', data, {key, dsaEncoding:'ieee-p1363'})
    private const string NodeSpki = "MFkwEwYHKoZIzj0CAQYIKoZIzj0DAQcDQgAEZcnQfLrA4DdhsXRR7WfoszfrgaTJZw+TwzDUnQ2azTF7Pr/1w8078OEECDo5u9Ym7jVOGSwk4W2m83LrcTEImg==";
    private const string NodeData = "grc-auth:device:AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=";
    private const string NodeSigP1363 = "8obwjZf98cOSvoAS85xFWK/cYwMpVd2Ypdr0v7goBvFUFeVbQzBwFHu8UfHCy16Xcb1Exx+pLdDsD+7TLerP9w==";
    private const string NodeSigDer = "MEUCIQCKOR+blv3a7rdJnftgHVunr6OrCCVMez/xdnWCCkv8mgIgU7j4PiHY7s6XTDC6DG32lQxU8uI+FJi1rDixyQMzxng=";
    private const string NodeId = "N2sIuipVCqRwZvYfw3QnRs";           // base64url(sha256(spki)).slice(0,22) computed by Node
    private const string NodeFingerprint = "376B-08BA-2A55-0AA4";       // first 8 bytes of sha256(spki), uppercase hex groups
    private const string NodeP384Spki = "MHYwEAYHKoZIzj0CAQYFK4EEACIDYgAEyE90dIARw6mC1aanjpvYzw/2QGUlRFY7D53XmxvWhHIMXFuQ2C1Ky24PloH1EYNOe233iabhp2x5b/3Ne0SRSmvs2YkUHorzOReTsFiaX18nJPGdxALdObfYeFT6gitN";

    [Fact] public void NodeVector_P1363Signature_Verifies() => Assert.True(IdentityUtil.Verify(NodeSpki, NodeData, NodeSigP1363));

    [Fact]
    public void NodeVector_IdAndFingerprint_MatchNodeFormula()
    {
        var spki = Convert.FromBase64String(NodeSpki);
        Assert.Equal(NodeId, IdentityUtil.DeriveId(spki));
        Assert.Equal(NodeFingerprint, IdentityUtil.Fingerprint(spki));
        Assert.Equal(22, IdentityUtil.DeriveId(spki).Length);
    }

    [Fact] public void NodeVector_DerSignature_IsRejected() => Assert.False(IdentityUtil.Verify(NodeSpki, NodeData, NodeSigDer));

    [Fact] public void NodeVector_TamperedData_Rejected() => Assert.False(IdentityUtil.Verify(NodeSpki, NodeData + "x", NodeSigP1363));

    [Fact]
    public void NodeVector_P384Key_NotAccepted()
    {
        Assert.Null(IdentityUtil.ParseP256Spki(NodeP384Spki));
        Assert.False(IdentityUtil.Verify(NodeP384Spki, NodeData, NodeSigP1363));
    }

    [Fact]
    public void Roundtrip_ValidSignature()
    {
        using var k = new TestKey();
        Assert.True(IdentityUtil.Verify(k.PublicKeyB64, "hello", k.Sign("hello")));
    }

    [Fact]
    public void TamperedData_Rejected()
    {
        using var k = new TestKey();
        Assert.False(IdentityUtil.Verify(k.PublicKeyB64, "hellp", k.Sign("hello")));
    }

    [Fact]
    public void TamperedSignature_Rejected()
    {
        using var k = new TestKey();
        var sig = Convert.FromBase64String(k.Sign("hello"));
        foreach (int i in new[] { 0, 31, 32, 63 })
        {
            var t = (byte[])sig.Clone(); t[i] ^= 0x01;
            Assert.False(IdentityUtil.Verify(k.PublicKeyB64, "hello", Convert.ToBase64String(t)));
        }
    }

    [Fact]
    public void WrongKey_Rejected()
    {
        using var a = new TestKey(); using var b = new TestKey();
        Assert.False(IdentityUtil.Verify(b.PublicKeyB64, "hello", a.Sign("hello")));
    }

    [Fact]
    public void DerFormattedSignature_Rejected()
    {
        using var k = new TestKey();
        var der = k.SignDer("hello");
        Assert.NotEqual(IdentityUtil.SignatureLength, Convert.FromBase64String(der).Length);
        Assert.False(IdentityUtil.Verify(k.PublicKeyB64, "hello", der));
    }

    [Fact]
    public void NonP256Key_Rejected()
    {
        using var k384 = new TestKey("p384", ECCurve.NamedCurves.nistP384);
        Assert.Null(IdentityUtil.ParseP256Spki(k384.PublicKeyB64));
        Assert.False(IdentityUtil.Verify(k384.PublicKeyB64, "x", k384.Sign("x")));
    }

    [Fact]
    public void RsaKey_Rejected()
    {
        using var rsa = RSA.Create(2048);
        Assert.Null(IdentityUtil.ParseP256Spki(Convert.ToBase64String(rsa.ExportSubjectPublicKeyInfo())));
    }

    [Fact]
    public void SpkiWithTrailingBytes_Rejected()
    {
        using var k = new TestKey();
        var padded = k.Spki.Concat(new byte[] { 0, 0 }).ToArray();
        Assert.Null(IdentityUtil.ParseP256Spki(Convert.ToBase64String(padded)));
    }

    [Theory]
    [InlineData(null)]
    [InlineData("")]
    [InlineData("not base64!!")]
    [InlineData("AAAA")]
    public void GarbageKeys_ReturnNull_NeverThrow(string? b64)
    {
        Assert.Null(IdentityUtil.ParseP256Spki(b64));
        Assert.False(IdentityUtil.Verify(b64, "x", "AAAA"));
    }

    [Fact] public void OversizedKey_Rejected() => Assert.Null(IdentityUtil.ParseP256Spki(new string('A', 401)));

    [Theory]
    [InlineData(null)]
    [InlineData("")]
    [InlineData("%%%")]
    public void GarbageSignatures_NeverThrow(string? sig)
    {
        using var k = new TestKey();
        Assert.False(IdentityUtil.Verify(k.PublicKeyB64, "x", sig));
    }

    [Fact]
    public void WrongLengthSignatures_Rejected()
    {
        using var k = new TestKey();
        Assert.False(IdentityUtil.Verify(k.PublicKeyB64, "x", Convert.ToBase64String(new byte[63])));
        Assert.False(IdentityUtil.Verify(k.PublicKeyB64, "x", Convert.ToBase64String(new byte[65])));
        Assert.False(IdentityUtil.Verify(k.PublicKeyB64, "x", Convert.ToBase64String(new byte[64]))); // all-zero r,s
        Assert.False(IdentityUtil.Verify(k.PublicKeyB64, "x", new string('A', 101)));
    }

    [Fact]
    public void SignedStrings_MatchProtocol()
    {
        Assert.Equal("grc-auth:device:N", IdentityUtil.AuthString("device", "N"));
        Assert.Equal("grc-session:S:N:D", IdentityUtil.SessionAuthString("S", "N", "D"));
        Assert.Equal("grc-offer:S:E:v=0", IdentityUtil.OfferString("S", "E", "v=0"));
        Assert.Equal("grc-answer:S:E:v=0", IdentityUtil.AnswerString("S", "E", "v=0"));
    }

    [Fact]
    public void RandomNonce_Is32Bytes_AndUnique()
    {
        var a = IdentityUtil.RandomNonce(); var b = IdentityUtil.RandomNonce();
        Assert.Equal(32, Convert.FromBase64String(a).Length);
        Assert.NotEqual(a, b);
    }

    [Fact]
    public void Base64Url_NoPaddingOrUnsafeChars()
    {
        var s = IdentityUtil.Base64Url(new byte[] { 0xFB, 0xFF, 0xFE, 0x01 });
        Assert.DoesNotContain('=', s); Assert.DoesNotContain('+', s); Assert.DoesNotContain('/', s);
        Assert.Equal("-__-AQ", s);
    }

    [Fact]
    public void DeviceIdentity_PersistsAndSignsVerifiably()
    {
        using var d = new TempDir();
        var file = d.File("key.bin");
        using var a = DeviceIdentity.LoadOrCreate(file);
        using var b = DeviceIdentity.LoadOrCreate(file);
        Assert.Equal(a.DeviceId, b.DeviceId);
        Assert.Equal(IdentityUtil.DeriveId(a.PublicKeySpki), a.DeviceId);
        Assert.Equal(IdentityUtil.Fingerprint(a.PublicKeySpki), a.Fingerprint);
        Assert.True(IdentityUtil.Verify(a.PublicKeyBase64, "grc-answer:x", b.Sign("grc-answer:x")));
        Assert.False(File.Exists(file + ".tmp"));
    }

    /// <summary>In-memory test protector: reversible, never DPAPI.</summary>
    private sealed class XorProtector : IKeyProtector
    {
        public int Protects, Unprotects;
        public byte[] Protect(byte[] d) { Protects++; return d.Select(b => (byte)(b ^ 0x5A)).ToArray(); }
        public byte[] Unprotect(byte[] d) { Unprotects++; return d.Select(b => (byte)(b ^ 0x5A)).ToArray(); }
    }

    [Fact]
    public void DeviceIdentity_CustomProtector_Seam_RoundTrips()
    {
        using var d = new TempDir();
        var file = d.File("key.bin");
        var prot = new XorProtector();
        using var a = DeviceIdentity.LoadOrCreate(file, prot);
        using var b = DeviceIdentity.LoadOrCreate(file, prot);
        Assert.Equal((1, 1), (prot.Protects, prot.Unprotects));
        Assert.Equal(a.DeviceId, b.DeviceId);
        // what's on disk is the protector's output, not a raw PKCS#8 key
        using var ec = ECDsa.Create();
        Assert.ThrowsAny<CryptographicException>(() => ec.ImportPkcs8PrivateKey(File.ReadAllBytes(file), out _));
    }

    [Fact]
    public void DeviceIdentity_Ephemeral_And_FromKey()
    {
        using var a = DeviceIdentity.CreateEphemeral();
        using var b = DeviceIdentity.CreateEphemeral();
        Assert.NotEqual(a.DeviceId, b.DeviceId);
        Assert.True(IdentityUtil.Verify(a.PublicKeyBase64, "x", a.Sign("x")));
        Assert.Throws<ArgumentException>(() => DeviceIdentity.FromKey(ECDsa.Create(ECCurve.NamedCurves.nistP384)));
        using var k = DeviceIdentity.FromKey(ECDsa.Create(ECCurve.NamedCurves.nistP256));
        Assert.Equal(22, k.DeviceId.Length);
    }

    [WindowsFact]
    public void DeviceIdentity_Default_IsDpapiCurrentUser()
    {
        using var d = new TempDir();
        var file = d.File("key.bin");
        using var a = DeviceIdentity.LoadOrCreate(file); // production path: no protector given
        var onDisk = File.ReadAllBytes(file);
        using var ec = ECDsa.Create();
        Assert.ThrowsAny<CryptographicException>(() => ec.ImportPkcs8PrivateKey(onDisk, out _));
        var pkcs8 = ProtectedData.Unprotect(onDisk, Encoding.UTF8.GetBytes("GlobalRemoteControl.DeviceKey.v1"), DataProtectionScope.CurrentUser);
        ec.ImportPkcs8PrivateKey(pkcs8, out _);
        Assert.Equal(a.PublicKeyBase64, Convert.ToBase64String(ec.ExportSubjectPublicKeyInfo()));
        Assert.Throws<CryptographicException>(() => ProtectedData.Unprotect(onDisk, null, DataProtectionScope.CurrentUser)); // entropy required
    }
}
